import {RACE_RULES} from "@qwordly/core/race";
import {applyRaceGuess, applyRaceHint, applyRaceSkip, abandonRaceRun, refreshRaceRun, type RaceRunRecord} from "../../race/raceEngine";
import {parseRunRecord} from "../../race/raceSetupService";

/** Full modern deck whose scoring transitions are generated by the real engine. */
const fixture = (): RaceRunRecord => ({recordVersion: 1, runId: "position", userId: "player", role: "creator", status: "active",
  categoryId: "history", locale: "en", rulesVersion: RACE_RULES.version, deckId: "deck",
  riddles: Array.from({length: 15}, (_, position) => ({riddleId: `q-${position}`, canonicalRiddleId: `c-${position}`,
    text: "A clue", answer: "test", position})), currentPosition: 0, correctCount: 0, guessesUsed: 0,
  hintUsed: false, revealedLetters: [], startedAtMs: 1000, hintPenaltyMs: 0, skipPenaltyMs: 0, events: []});

it.each(["correct", "automatic", "paid", "hinted"] as const)("accepts every actual modern %s clearing transition with and without retained history", method => {
  /** Validate intermediate questions as well as the tenth clearing action which stays on its final question. */
  let run = fixture();
  /** Deterministic increasing accepted action time. */
  let nowMs = 2000;
  for (let cleared = 0; cleared < 10; cleared++) {
    /** Actions use the actual current immutable question. */
    const riddleId = run.riddles[run.currentPosition].riddleId;
    if (method === "hinted") {
      run = applyRaceHint(run, {riddleId}, nowMs++).run;
      expect(parseRunRecord(run)).toEqual(run);
    }
    if (method === "automatic") {
      for (let guess = 0; guess < RACE_RULES.maxGuessesPerRiddle; guess++) {
        run = applyRaceGuess(run, {riddleId, guess: "xxxx"}, nowMs++).run;
        expect(parseRunRecord(run)).toEqual(run);
      }
    } else if (method === "paid") run = applyRaceSkip(run, {riddleId}, nowMs++);
    else run = applyRaceGuess(run, {riddleId, guess: "test"}, nowMs++).run;
    expect(parseRunRecord(run)).toEqual(run);
    expect(parseRunRecord({...run, events: []})).toMatchObject({correctCount: cleared + 1});
  }
  expect(run).toMatchObject({status: "completed", correctCount: 10, currentPosition: 9});
});

it("accepts prepared, scheduled, deadline and abandoned positions generated from real modern progress", () => {
  /** Readiness remains at zero before any scoring action. */
  const prepared = {...fixture(), status: "prepared", startedAtMs: 0, preparationExpiresAtMs: 30000};
  expect(parseRunRecord(prepared)).toEqual(prepared);
  /** The countdown keeps that same owned question and score. */
  const scheduled = {...fixture(), status: "scheduled", startedAtMs: 5000};
  expect(parseRunRecord(scheduled)).toEqual(scheduled);
  /** One real clear advances to question two before interruption. */
  const progressed = applyRaceGuess(fixture(), {riddleId: "q-0", guess: "test"}, 2000).run;
  expect(parseRunRecord(abandonRaceRun(progressed, 3000))).toMatchObject({currentPosition: 1, correctCount: 1});
  /** Challenger deadline preserves the last accepted progress. */
  const challenger = {...progressed, role: "challenger" as const, opponent: {displayName: "Rival", adjustedFinishMs: 10000, events: []}};
  expect(parseRunRecord(refreshRaceRun(challenger, 12000))).toMatchObject({status: "completed", currentPosition: 1, correctCount: 1});
});

it.each([undefined, 1] as const)("rejects a score ahead of the owned active position even with no events, version=%s", recordVersion => {
  /** Supported legacy reads omit the revision; modern data must also match every clearing count. */
  const {recordVersion: _version, ...legacy} = fixture();
  expect(() => parseRunRecord({...legacy, ...(recordVersion ? {recordVersion} : {}), correctCount: 2, currentPosition: 1}))
    .toThrow("Stored Race to 10 run is invalid.");
});

it("preserves old non-clearing skips while rejecting that contradiction in a modern run", () => {
  /** Historical skips advanced a question without adding a clear. */
  const {recordVersion: _version, ...legacy} = fixture();
  expect(parseRunRecord({...legacy, correctCount: 2, currentPosition: 4})).toMatchObject({correctCount: 2, currentPosition: 4});
  expect(() => parseRunRecord({...fixture(), correctCount: 2, currentPosition: 4})).toThrow("Stored Race to 10 run is invalid.");
  /** A legacy tenth clear may follow non-clearing skips late in the fifteen-question deck. */
  const terminal = applyRaceGuess({...legacy, correctCount: 9, currentPosition: 14}, {riddleId: "q-14", guess: "test"}, 2000).run;
  expect(parseRunRecord({...terminal, events: []})).toMatchObject({correctCount: 10, currentPosition: 14});
  expect(() => parseRunRecord({...terminal, recordVersion: 1, events: []})).toThrow("Stored Race to 10 run is invalid.");
});
